//! The engine host binaries the app downloads on demand, one pinned list per (engine, platform).
//!
//! Everything between `// BEGIN TABLE` and `// END TABLE` is generated by `gate host-pin --adopt`; do not edit it by
//! hand. A pin names the exact file a `hosts-KIND-FP` release holds (PE output is not bit-reproducible, so a rebuild
//! is a different artifact), and its URL carries the source fingerprint `gate host-fingerprint` computes;
//! `gate host-pin --check` fails when it is stale. A kind with no entry has no download in this build.

use crate::process_manager::ViewKind;

/// One downloadable host file.
#[derive(Debug, PartialEq, Eq)]
pub struct Component {
    /// The file name it installs under (`manifold-engine-cef.exe`).
    pub file: &'static str,
    /// Where it is fetched from: `https://github.com/winstonyli/manifold/releases/download/v<ver>/<file>-<platform>`.
    /// Untrusted: only `sha256` is the trust anchor. A reused host points at the older release's asset.
    pub url: &'static str,
    pub size: u64,
    /// Lowercase hex SHA-256 of the file.
    pub sha256: &'static str,
}

/// The components of one engine on one platform (`windows-x64` or `linux-x64`).
#[derive(Debug)]
pub struct Entry {
    pub kind: ViewKind,
    pub platform: &'static str,
    pub components: &'static [Component],
}

// BEGIN TABLE
#[rustfmt::skip]
const TABLE: &[Entry] = &[
    Entry { kind: ViewKind::Cef, platform: "windows-x64", components: &[
        Component { file: "manifold-engine-cef.exe", url: "https://github.com/winstonyli/manifold/releases/download/hosts-cef-a3623229bc84/manifold-engine-cef.exe-windows-x64", size: 763392, sha256: "283fb18a33d3cf579af319c4543814bea6bcebf1593f15bba8ffce342309f917" },
    ] },
];
// END TABLE

/// The components `kind` needs on `platform`, or an empty slice when this build pins none.
pub fn components_for(kind: ViewKind, platform: &str) -> &'static [Component] {
    lookup(TABLE, kind, platform)
}

fn lookup(table: &'static [Entry], kind: ViewKind, platform: &str) -> &'static [Component] {
    table.iter().find(|e| e.kind == kind && e.platform == platform).map_or(&[], |e| e.components)
}

/// What is wrong with `table`, if anything: well-formed hashes, sizes and URLs, and stable order.
#[cfg(test)]
fn check_table(table: &[Entry]) -> Result<(), String> {
    let key = |e: &Entry| (e.kind.desc().name, e.platform);
    for pair in table.windows(2) {
        if key(&pair[0]) >= key(&pair[1]) {
            return Err(format!("entries out of order or duplicated at {:?}", key(&pair[1])));
        }
    }
    for e in table {
        for pair in e.components.windows(2) {
            if pair[0].file >= pair[1].file {
                return Err(format!("{:?}: files out of order at {}", key(e), pair[1].file));
            }
        }
        for c in e.components {
            let who = format!("{:?} {}", key(e), c.file);
            if c.sha256.len() != 64 || !c.sha256.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f')) {
                return Err(format!("{who}: sha256 is not 64 lowercase hex digits"));
            }
            if c.size == 0 {
                return Err(format!("{who}: size is zero"));
            }
            let last = c.url.strip_prefix("https://").and_then(|rest| rest.rsplit('/').next());
            if last != Some(&format!("{}-{}", c.file, e.platform)) {
                return Err(format!("{who}: url must be https and end in /{}-{}", c.file, e.platform));
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    const HASH: &str = "db3e0751979c3cb3068f732ed4f0ef12ade69d183d98ceee120ad08c8d00f74c";

    const fn comp(file: &'static str, url: &'static str, size: u64, sha256: &'static str) -> Component {
        Component { file, url, size, sha256 }
    }

    const URL_CEF: &str =
        "https://github.com/winstonyli/manifold/releases/download/hosts-cef-0123456789ab/manifold-engine-cef.exe-windows-x64";
    const URL_SERVO: &str =
        "https://github.com/winstonyli/manifold/releases/download/hosts-servo-0123456789ab/manifold-engine-servo.exe-windows-x64";

    static GOOD: &[Entry] = &[
        Entry {
            kind: ViewKind::Cef,
            platform: "windows-x64",
            components: &[comp("manifold-engine-cef.exe", URL_CEF, 740_000, HASH)],
        },
        Entry {
            kind: ViewKind::Servo,
            platform: "windows-x64",
            components: &[comp("manifold-engine-servo.exe", URL_SERVO, 90_000_000, HASH)],
        },
    ];

    fn one(c: &'static [Component]) -> Vec<Entry> {
        vec![Entry { kind: ViewKind::Cef, platform: "windows-x64", components: c }]
    }

    #[test]
    fn the_checked_in_table_is_well_formed() {
        check_table(TABLE).unwrap();
    }

    #[test]
    fn a_good_table_passes() {
        check_table(GOOD).unwrap();
    }

    #[test]
    fn lookup_finds_by_kind_and_platform_and_is_empty_otherwise() {
        assert_eq!(lookup(GOOD, ViewKind::Cef, "windows-x64")[0].file, "manifold-engine-cef.exe");
        assert!(lookup(GOOD, ViewKind::Cef, "plan9-x64").is_empty());
        assert!(lookup(GOOD, ViewKind::Webkit, "windows-x64").is_empty());
        assert!(components_for(ViewKind::Cef, "plan9-x64").is_empty());
    }

    #[test]
    fn a_bad_hash_fails() {
        for bad in ["", "abc", &HASH.to_uppercase(), &HASH[1..], &format!("{HASH}0"), &HASH.replace('d', "g")] {
            let bad: &'static str = Box::leak(bad.to_string().into_boxed_str());
            let c: &'static [Component] = Box::leak(Box::new([comp("manifold-engine-cef.exe", URL_CEF, 1, bad)]));
            assert!(check_table(&one(c)).is_err(), "accepted sha256 {bad:?}");
        }
    }

    #[test]
    fn a_zero_size_fails() {
        let c: &'static [Component] = Box::leak(Box::new([comp("manifold-engine-cef.exe", URL_CEF, 0, HASH)]));
        assert!(check_table(&one(c)).is_err());
    }

    #[test]
    fn a_url_that_is_not_https_or_not_the_file_and_platform_fails() {
        for url in [
            "http://example.com/v1/manifold-engine-cef.exe-windows-x64",
            "https://example.com/v1/manifold-engine-cef.exe-linux-x64",
            "https://example.com/v1/manifold-engine-cef.exe",
            "https://example.com/v1/other.exe-windows-x64",
            "https://example.com/v1/manifold-engine-cef.exe-windows-x64/",
        ] {
            let c: &'static [Component] = Box::leak(Box::new([comp("manifold-engine-cef.exe", url, 1, HASH)]));
            assert!(check_table(&one(c)).is_err(), "accepted url {url}");
        }
    }

    #[test]
    fn an_older_releases_url_is_fine() {
        let url = "https://example.com/releases/download/v1.0.0/manifold-engine-cef.exe-windows-x64";
        let c: &'static [Component] = Box::leak(Box::new([comp("manifold-engine-cef.exe", url, 1, HASH)]));
        check_table(&one(c)).unwrap();
    }

    #[test]
    fn the_table_must_be_sorted_by_kind_then_platform_then_file() {
        // Entries out of order (servo before cef; kinds sort by store name).
        static BAD_KINDS: &[Entry] = &[
            Entry {
                kind: ViewKind::Servo,
                platform: "windows-x64",
                components: &[comp("manifold-engine-servo.exe", URL_SERVO, 1, HASH)],
            },
            Entry {
                kind: ViewKind::Cef,
                platform: "windows-x64",
                components: &[comp("manifold-engine-cef.exe", URL_CEF, 1, HASH)],
            },
        ];
        assert!(check_table(BAD_KINDS).is_err());
        // Files out of order within one entry.
        static BAD_FILES: &[Entry] = &[Entry {
            kind: ViewKind::Cef,
            platform: "windows-x64",
            components: &[
                comp("b.exe", "https://x/v/b.exe-windows-x64", 1, HASH),
                comp("a.exe", "https://x/v/a.exe-windows-x64", 1, HASH),
            ],
        }];
        assert!(check_table(BAD_FILES).is_err());
        // A duplicated (kind, platform) is not strictly increasing either.
        static DUP: &[Entry] = &[
            Entry { kind: ViewKind::Cef, platform: "windows-x64", components: &[] },
            Entry { kind: ViewKind::Cef, platform: "windows-x64", components: &[] },
        ];
        assert!(check_table(DUP).is_err());
    }
}
